CREATE TABLE public.estimating_catalog (id text PRIMARY KEY, kind text NOT NULL CHECK (kind IN ('labour','material','productivity','template','benchmark','expense')), name text NOT NULL, data jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.estimating_catalog TO authenticated; GRANT ALL ON public.estimating_catalog TO service_role;
ALTER TABLE public.estimating_catalog ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin pricing control" ON public.estimating_catalog FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.estimating_settings (id integer PRIMARY KEY DEFAULT 1 CHECK(id=1), markup_percent integer NOT NULL DEFAULT 12 CHECK(markup_percent BETWEEN 10 AND 15), vat_registered boolean, sales_vat_percent integer NOT NULL DEFAULT 20 CHECK(sales_vat_percent BETWEEN 0 AND 20), tax_confirmed boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,INSERT ON public.estimating_settings TO authenticated; GRANT ALL ON public.estimating_settings TO service_role;
ALTER TABLE public.estimating_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin business settings" ON public.estimating_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.estimating_sessions (id uuid PRIMARY KEY, token_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.estimating_sessions TO authenticated; GRANT ALL ON public.estimating_sessions TO service_role;
ALTER TABLE public.estimating_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin session review" ON public.estimating_sessions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.estimate_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES public.estimating_sessions(id), specification jsonb NOT NULL, pricing_snapshot jsonb NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.estimate_versions TO authenticated; GRANT ALL ON public.estimate_versions TO service_role;
ALTER TABLE public.estimate_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin estimate review" ON public.estimate_versions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE INDEX estimate_session_created ON public.estimate_versions(session_id,created_at DESC);
CREATE TABLE public.estimate_actuals (estimate_id uuid PRIMARY KEY REFERENCES public.estimate_versions(id), labour_pence bigint NOT NULL DEFAULT 0 CHECK(labour_pence>=0), material_pence bigint NOT NULL DEFAULT 0 CHECK(material_pence>=0), specialist_pence bigint NOT NULL DEFAULT 0 CHECK(specialist_pence>=0), other_pence bigint NOT NULL DEFAULT 0 CHECK(other_pence>=0), actual_person_days numeric NOT NULL DEFAULT 0 CHECK(actual_person_days>=0), notes text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.estimate_actuals TO authenticated; GRANT ALL ON public.estimate_actuals TO service_role;
ALTER TABLE public.estimate_actuals ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin actual costs" ON public.estimate_actuals FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.estimate_uploads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES public.estimating_sessions(id), storage_path text NOT NULL UNIQUE, name text NOT NULL, mime_type text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.estimate_uploads TO authenticated; GRANT ALL ON public.estimate_uploads TO service_role;
ALTER TABLE public.estimate_uploads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin uploaded plans" ON public.estimate_uploads FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin estimate file reads" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='estimate-uploads' AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.estimating_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, record_id text NOT NULL, previous_data jsonb, next_data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.estimating_audit TO authenticated; GRANT ALL ON public.estimating_audit TO service_role;
ALTER TABLE public.estimating_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admin pricing history" ON public.estimating_audit FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.audit_estimating_catalog() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL THEN INSERT INTO public.estimating_audit(user_id,record_id,previous_data,next_data) VALUES(auth.uid(),NEW.id,to_jsonb(OLD),to_jsonb(NEW)); END IF; RETURN NEW; END; $$;
CREATE TRIGGER estimating_catalog_audit AFTER INSERT OR UPDATE ON public.estimating_catalog FOR EACH ROW EXECUTE FUNCTION public.audit_estimating_catalog();